UsageLimitCard: FC<UsageLimitCardProps> = ({
  data,
  labels,
  styles: stylesProp,
}) => {
  const { colors, typography } = stylesProp ?? {};
  const {
    titleClassName = 'dial-body-semi-text',
    amountClassName = 'dial-display1-text',
    secondaryAmountClassName = 'dial-small-text',
    badgeClassName = 'dial-caption-lead-semi-text',
    usedPercentLabelClassName = 'dial-small-text',
    resetLabelClassName = 'dial-tiny-text',
  } = typography ?? {};

  const cssVars = buildCssVars({
    '--uld-card-bg': colors?.cardBackground,
    '--uld-title': colors?.titleColor,
    '--uld-default-accent': colors?.defaultAccentColor,
    '--uld-default-progress': colors?.defaultProgressColor,
    '--uld-warning-accent': colors?.warningAccentColor,
    '--uld-warning-progress': colors?.warningProgressColor,
    '--uld-error-accent': colors?.errorAccentColor,
    '--uld-error-progress': colors?.errorProgressColor,
    '--uld-secondary-amount': colors?.secondaryAmountColor,
    '--uld-progress-track': colors?.progressTrackColor,
    '--uld-default-badge-bg': colors?.defaultBadgeBackground,
    '--uld-default-badge-text': colors?.defaultBadgeColor,
    '--uld-warning-badge-bg': colors?.warningBadgeBackground,
    '--uld-warning-badge-text': colors?.warningBadgeColor,
    '--uld-error-badge-bg': colors?.errorBadgeBackground,
    '--uld-error-badge-text': colors?.errorBadgeColor,
    '--uld-used-percent-label': colors?.usedPercentLabelColor,
  });

  const badgeLabel = getBadgeLabel(data.status, labels);

  return (
    <div
      className={mergeClasses(
        'flex min-w-0 flex-col gap-4 rounded-xl px-6 py-5 shadow-md',
        styles.card,
        USAGE_DASHBOARD_CLASS.card,
      )}
      style={cssVars}
      role="group"
      aria-label={`${data.title}, ${data.periodDescription}`}
    >
      <div className="flex items-center justify-between gap-2">
        <p className={mergeClasses('m-0', titleClassName, styles.title)}>
          {data.title}
        </p>
        <span
          className={mergeClasses(
            'shrink-0 rounded-full px-2 py-1',
            badgeClassName,
            data.status === UsageLimitStatus.Default && styles.defaultBadge,
            data.status === UsageLimitStatus.RunningLow && styles.warningBadge,
            data.status === UsageLimitStatus.LimitReached && styles.errorBadge,
          )}
        >
          {badgeLabel}
        </span>
      </div>

      <div className="flex flex-col gap-2">
        <p className="m-0 flex flex-wrap items-baseline gap-2">
          <span
            className={mergeClasses(
              amountClassName,
              styles.amount,
              data.status === UsageLimitStatus.Default && styles.defaultAccent,
              data.status === UsageLimitStatus.RunningLow &&
                styles.warningAccent,
              data.status === UsageLimitStatus.LimitReached &&
                styles.errorAccent,
            )}
          >
            {data.usedLabel}
          </span>
          {!data.isUnlimited && data.totalLabel != null && (
            <span
              className={mergeClasses(
                secondaryAmountClassName,
                styles.secondaryAmount,
              )}
            >
              {labels.usedOfTotalLabel({ total: data.totalLabel })}
            </span>
          )}
        </p>

        {!data.isUnlimited && data.usedPercent != null && (
          <>
            <ProgressBar
              value={Math.min(data.usedPercent, 100)}
              max={100}
              size={ElementSize.Small}
              className={mergeClasses(
                '!h-1 w-full',
                styles.progressTrack,
                data.status === UsageLimitStatus.Default &&
                  styles.progressFillDefault,
                data.status === UsageLimitStatus.RunningLow &&
                  styles.progressFillWarning,
                data.status === UsageLimitStatus.LimitReached &&
                  styles.progressFillDanger,
              )}
              aria-label={data.title}
              aria-valuetext={data.progressAriaLabel}
            />
            <div className="flex items-center justify-between gap-2">
              {data.remainingLabel != null && (
                <span
                  className={mergeClasses(
                    secondaryAmountClassName,
                    styles.secondaryAmount,
                  )}
                >
                  {labels.remainingCaptionLabel({
                    remaining: data.remainingLabel,
                  })}
                </span>
              )}
              <span
                className={mergeClasses(
                  'ms-auto',
                  usedPercentLabelClassName,
                  styles.usedPercentLabel,
                )}
              >
                {labels.usedPercentLabel({
                  percent: Math.min(Math.round(data.usedPercent), 100),
                })}
              </span>
            </div>
          </>
        )}

        {/* Rendered for an unlimited card too — an unconfigured limit still
            accumulates spend against a period that rolls over. */}
        {data.resetLabel != null && (
          <span className="contents">
            {/* `aria-label` is not reliably supported on a bare `<time>`, so the
                spoken form — which names the timezone in full rather than as an
                offset — is carried by a visually-hidden sibling instead. */}
            <time
              dateTime={data.resetIsoValue}
              aria-hidden={data.resetAriaLabel != null || undefined}
              className={mergeClasses(
                'block break-words',
                resetLabelClassName,
                styles.secondaryAmount,
              )}
            >
              {data.resetLabel}
            </time>
            {data.resetAriaLabel != null && (
              <span className="sr-only">{data.resetAriaLabel}</span>
            )}
          </span>
        )}
      </div>
    </div>
  );
}

UsageLimitCardGroup: FC<UsageLimitCardGroupProps> = ({
  cards,
  labels,
  styles: stylesProp,
}) => {
  if (cards.length === 0) {
    return null;
  }

  return (
    <div
      className={mergeClasses(
        'grid grid-cols-1 gap-4 desktop:grid-cols-[repeat(var(--uld-card-count),minmax(0,1fr))]',
        USAGE_DASHBOARD_CLASS.cardGroup,
      )}
      style={{ '--uld-card-count': cards.length } as CSSProperties}
    >
      {cards.map((card) => (
        <UsageLimitCard
          key={card.title}
          data={card}
          labels={labels}
          styles={stylesProp}
        />
      ))}
    </div>
  );
}

export enum UsageLimitStatus {
  /** Below the running-low threshold. Rendered with the default (blue) accent and a "within limits" badge. */
  Default = 'default',
  /** At or above the running-low threshold but below 100% used. Rendered with the warning (amber) accent and badge. */
  RunningLow = 'runningLow',
  /** At or above 100% used. Rendered with the error (red) accent and badge. */
  LimitReached = 'limitReached',
}

export interface UsageLimitCardData {
  /** Card title, e.g. `'Today'` / `'This week'` / `'This month'`. */
  title: string;
  /** Accessible description of the calendar period, e.g. `'Today'`, appended to the card's accessible group name. */
  periodDescription: string;
  /** Raw used amount, already clamped to `>= 0` by the host. Used only to drive `progressAriaLabel`/text — the library never recomputes it. */
  used: number;
  /** Raw total amount. Ignored when `isUnlimited` is `true`. */
  total: number;
  /** Preformatted used amount, e.g. `'$3.60'`. Always the card's prominent figure. */
  usedLabel: string;
  /** Preformatted total amount, e.g. `'$4.00'`, passed to `labels.usedOfTotalLabel`. Omitted when `isUnlimited` is `true`. */
  totalLabel?: string;
  /** Preformatted remaining amount, e.g. `'$0.40'`, passed to `labels.remainingCaptionLabel`. Omitted when `isUnlimited` is `true`. */
  remainingLabel?: string;
  /** Whether the host detected the unlimited sentinel or an otherwise-unusable total. When `true`, only `usedLabel` is shown — no progress bar, ratio, or badge. */
  isUnlimited?: boolean;
  /** Used percentage, not pre-clamped — may exceed 100. The card clamps both the progress-bar fill and the visible percent label at 100%; only `progressAriaLabel` conveys the real, uncapped value. Ignored when `isUnlimited` is `true`. */
  usedPercent?: number;
  /** Status the host derived from `usedPercent` against its own thresholds. */
  status: UsageLimitStatus;
  /** Accessible value text for the progress bar (`aria-valuetext`), e.g. `'$3.60 of $4.00, 90% used'`. */
  progressAriaLabel: string;
  /*
   * The reset-time trio is host-preformatted. The library renders these
   * strings verbatim and never parses, formats, or timezone-shifts them — it
   * imports no `Intl`, and accepts no locale, timezone, or raw timestamp. All
   * three are absent together when the host could not format a reset time, in
   * which case the card renders exactly as it did before reset times existed.
   */
  /** Visible reset line, e.g. `'Resets Sep 16, 2026, 2:00 AM GMT+2'`. */
  resetLabel?: string;
  /** Machine-readable instant for the reset line's `<time dateTime>` attribute, e.g. `'2026-09-16T00:00:00Z'`. */
  resetIsoValue?: string;
  /** Accessible expansion of the reset line, applied as its `aria-label` when supplied. */
  resetAriaLabel?: string;
}

